import { useEffect, useState } from 'react';
import { collection, deleteDoc, doc, getDocs, query, setDoc, updateDoc } from 'firebase/firestore';
import { getAuth, onAuthStateChanged, signInWithPopup, GoogleAuthProvider } from 'firebase/auth';
import { db } from './firebase';

interface Note {
  id: string;
  ownerId: string;
  text: string;
}

export default function App() {
  const [user, setUser] = useState<{ uid: string } | null>(null);
  const [notes, setNotes] = useState<Note[]>([]);
  const [draft, setDraft] = useState('');

  useEffect(
    () => onAuthStateChanged(getAuth(), (u) => setUser(u ? { uid: u.uid } : null)),
    [],
  );

  async function refresh() {
    const snap = await getDocs(query(collection(db, 'notes')));
    setNotes(snap.docs.map((d) => ({ id: d.id, ...(d.data() as Omit<Note, 'id'>) })));
  }

  useEffect(() => {
    if (user) void refresh();
  }, [user]);

  async function addNote() {
    if (!user || !draft.trim()) return;
    const id = `n${Date.now().toString(36)}`;
    await setDoc(doc(db, 'notes', id), { ownerId: user.uid, text: draft.trim() });
    setDraft('');
    await refresh();
  }

  async function editNote(id: string, text: string) {
    await updateDoc(doc(db, 'notes', id), { text });
    await refresh();
  }

  async function removeNote(id: string) {
    await deleteDoc(doc(db, 'notes', id));
    await refresh();
  }

  if (!user) {
    return (
      <main>
        <h1>Notes</h1>
        <button onClick={() => signInWithPopup(getAuth(), new GoogleAuthProvider())}>
          Sign in with Google
        </button>
      </main>
    );
  }

  return (
    <main>
      <h1>Notes</h1>
      <p data-testid="signed-in-as">Signed in as {user.uid}</p>
      <input
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        placeholder="Write a note…"
      />
      <button onClick={addNote}>Add note</button>
      <ul data-testid="note-list">
        {notes.map((n) => (
          <li key={n.id}>
            <span>{n.text}</span>
            {n.ownerId === user.uid && (
              <>
                <button onClick={() => editNote(n.id, `${n.text} (edited)`)}>Edit</button>
                <button onClick={() => removeNote(n.id)}>Delete</button>
              </>
            )}
          </li>
        ))}
      </ul>
    </main>
  );
}

